function guidePointerPos(target, sellerMode) {
  if (target.profile) return { x: 326, y: 44 };
  const keys = sellerMode ? GUIDE_SELLER_NAV_KEYS : GUIDE_BUYER_NAV_KEYS;
  const idx = keys.indexOf(target.tab);
  if (idx === -1) return null;
  const slot = 346 / keys.length;
  return { x: slot * (idx + 0.5), y: 680 };
}
