function GuideOverlay({ steps, step, onBack, onNext, onFinish, onSkip, color, pointer }) {
  const s = steps[step];
  const Icon = s.icon;
  const isFirst = step === 0;
  const isLast = step === steps.length - 1;
  const tailX = pointer ? Math.max(14, Math.min(322 - 14, pointer.x - 12)) - 7 : null;
  return (
    <>
      <div className="absolute inset-0" style={{ background: "rgba(20,19,17,0.55)", zIndex: 60 }} />
      {pointer && (
        <div className="absolute pulse-ring" style={{ left: pointer.x - 5, top: pointer.y - 5, width: 10, height: 10, borderRadius: 999, background: color, zIndex: 65, pointerEvents: "none" }} />
      )}
      <div className="absolute left-0 right-0 px-3" style={{ bottom: 78, zIndex: 70 }}>
        <div className="rounded-2xl p-4 pop-in relative" key={step} style={{ background: C.bg, boxShadow: "0 -6px 18px rgba(0,0,0,0.15), 0 12px 30px rgba(0,0,0,0.3)", border: `1px solid ${C.line}` }}>
          {tailX !== null && (
            <div style={{ position: "absolute", left: tailX, bottom: -7, width: 0, height: 0, borderLeft: "7px solid transparent", borderRight: "7px solid transparent", borderTop: `7px solid ${C.bg}` }} />
          )}
          <div className="flex items-center gap-1 mb-3">
            {steps.map((_, i) => (<div key={i} style={{ flex: 1, height: 3, borderRadius: 999, background: i <= step ? color : C.line }} />))}
          </div>
          <div className="flex items-start gap-3 mb-3">
            <div className="rounded-full flex items-center justify-center flex-shrink-0" style={{ width: 38, height: 38, background: `${color}1A` }}>
              <Icon size={18} color={color} />
            </div>
            <div className="flex-1 min-w-0">
              <span className="text-[9px] font-bold uppercase tracking-wide" style={{ color }}>{step + 1}/{steps.length}</span>
              <p className="font-bold text-sm mt-1" style={{ color: C.ink }}>{s.title}</p>
              <p className="text-[11px] leading-snug mt-1" style={{ color: C.inkSoft }}>{s.desc}</p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            {!isFirst && <button onClick={onBack} className="rounded-full px-4 py-2.5 font-bold text-xs flex-shrink-0" style={{ border: `1px solid ${C.line}`, color: C.ink }}>Kembali</button>}
            <button onClick={isLast ? onFinish : onNext} className="flex-1 rounded-full py-2.5 font-bold text-xs" style={{ background: C.ink, color: "#fff" }}>{isLast ? "Selesai" : "Lanjut"}</button>
          </div>
          {!isLast && <button onClick={onSkip} className="w-full text-center text-[10px] font-semibold mt-2" style={{ color: C.inkFaint }}>Lewati Panduan</button>}
        </div>
      </div>
    </>
  );
}

