function MonthCalendar({ items, rangeMode, onDateClick, selectedDate }) {
  const today = new Date();
  const year = today.getFullYear(), month = today.getMonth();
  const first = new Date(year, month, 1);
  const startOffset = first.getDay();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const byDate = {};
  const addToDate = (key, entry) => { byDate[key] = byDate[key] || []; byDate[key].push(entry); };

  items.forEach((it) => {
    const expiryDate = new Date(today); expiryDate.setDate(expiryDate.getDate() + it.expiryDays);
    if (rangeMode && it.listedDate) {
      const startDate = new Date(it.listedDate + "T00:00:00");
      const cursor = new Date(startDate);
      while (cursor.getTime() <= expiryDate.getTime()) {
        if (cursor.getMonth() === month && cursor.getFullYear() === year) {
          const isExpiryDay = cursor.getFullYear() === expiryDate.getFullYear() && cursor.getMonth() === expiryDate.getMonth() && cursor.getDate() === expiryDate.getDate();
          addToDate(cursor.getDate(), { ...it, isExpiryDay });
        }
        cursor.setDate(cursor.getDate() + 1);
      }
    } else if (expiryDate.getMonth() === month && expiryDate.getFullYear() === year) {
      addToDate(expiryDate.getDate(), { ...it, isExpiryDay: true });
    }
  });
  const cells = [];
  for (let i = 0; i < startOffset; i++) cells.push(null);
  for (let d = 1; d <= daysInMonth; d++) cells.push(d);

  return (
    <div>
      <div className="grid grid-cols-7 mb-1.5">
        {["M", "S", "S", "R", "K", "J", "S"].map((d, i) => <div key={i} className="text-center text-[9px] font-bold" style={{ color: C.inkFaint }}>{d}</div>)}
      </div>
      <div className="grid grid-cols-7 gap-y-1.5">
        {cells.map((d, i) => {
          if (d === null) return <div key={i} />;
          const isToday = d === today.getDate();
          const isSelected = selectedDate === d;
          const dayItems = byDate[d];
          let dotColor = null; let hasExpiryDay = false;
          if (dayItems && dayItems.length) {
            hasExpiryDay = dayItems.some((it) => it.isExpiryDay);
            const worstTier = dayItems.reduce((acc, it) => { if (!it.isExpiryDay) return acc; const t = tierOf(it.expiryDays); const order = { red: 0, orange: 1, yellow: 2, green: 3 }; return order[t] < order[acc] ? t : acc; }, "green");
            dotColor = hasExpiryDay ? URGENCY_COLOR[worstTier] : C.accent;
          }
          const Wrapper = onDateClick ? "button" : "div";
          return (
            <Wrapper key={i} onClick={onDateClick ? () => onDateClick(d, dayItems || []) : undefined} className="flex flex-col items-center gap-0.5">
              <div className="flex items-center justify-center" style={{ width: 24, height: 24, borderRadius: 999, background: isToday ? C.ink : isSelected ? C.accentSoft : "transparent", border: isSelected && !isToday ? `1.5px solid ${C.accentDeep}` : "none" }}>
                <span className="text-[11px] font-semibold" style={{ color: isToday ? "#fff" : isSelected ? C.accentDeep : C.ink }}>{d}</span>
              </div>
              <div style={{ width: 4, height: 4, borderRadius: 999, background: dotColor || "transparent", opacity: dayItems && !hasExpiryDay ? 0.55 : 1 }} />
            </Wrapper>
          );
        })}
      </div>
    </div>
  );
}

