                    {scanStep === "preview" && scanImage && (<div><img src={scanImage} alt="produk" className="w-full rounded-xl" style={{ maxHeight: 220, objectFit: "cover" }} /><div className="mt-4"><PrimaryButton onClick={startEligibilityForm}>Lanjut Isi Data Produk</PrimaryButton></div></div>)}
