                        {o.status === "assigned" && <p className="text-center text-xs font-semibold" style={{ color: C.accentDeep }}>Driver sedang menuju tokomu buat jemput pesanan.</p>}
                        {o.status === "delivered" && <p className="text-center text-xs font-semibold" style={{ color: C.ok }}>Pesanan udah diterima pembeli.</p>}
                      </>
