                    <div className="rounded-full flex items-center justify-center flex-shrink-0" style={{ width: 44, height: 44, background: sellerMapPartnerInfo.type === "compost" ? C.okSoft : C.accentSoft }}><Sprout size={20} color={sellerMapPartnerInfo.type === "compost" ? C.ok : C.accentDeep} /></div>
